"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["291"],{1112(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>h,frontMatter:()=>s,contentTitle:()=>r,toc:()=>l,assets:()=>c});var a=JSON.parse('{"id":"how-to/hardware/samples/generic-rest","title":"Enable a connection to AirVantage using REST","description":"av \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/how-to/hardware/samples/generic-rest.md","sourceDirName":"how-to/hardware/samples","slug":"/how-to/hardware/samples/generic-rest","permalink":"/personal-av-docs/docs/how-to/hardware/samples/generic-rest","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/how-to/hardware/samples/generic-rest.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Enable a connection to AirVantage using REST","sidebar_label":"Enable a connection to AirVantage using ","sidebar_position":99,"edition":"av","source":"https://doc.airvantage.net/av/howto/hardware/samples/generic-rest","format":"md"}}'),i=n(4848),o=n(8453);let s={title:"Enable a connection to AirVantage using REST",sidebar_label:"Enable a connection to AirVantage using ",sidebar_position:99,edition:"av",source:"https://doc.airvantage.net/av/howto/hardware/samples/generic-rest",format:"md"},r,c={},l=[];function d(e){let t={a:"a",p:"p",strong:"strong",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)(t.p,{children:[":::note Edition\n",(0,i.jsx)(t.strong,{children:"av"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,i.jsx)(t.a,{href:"https://doc.airvantage.net/av/howto/hardware/samples/generic-rest",children:"Original page"}),".\n:::"]}),"\n",(0,i.jsxs)(t.p,{children:['Enable a connection to AirVantage using REST\nThis article explains the different steps to enable AirVantage connection for any device using REST.\n1 /\nSetup\n2 /\nDesign\n3 /\nImplementing\nStep 1: Setup Hardware\nPlug the device to USB.\nSet up Internet on your device with an ethernet cable.\nInstall the device developer tools\nStep 2: Design your application\nAn\napplication model\naims to explain to AirVantage how to deal with the device about communication and authentication and managing the data: variable, settings or commands.\nIf you don\u2019t supply such information, the server will ignore all the communication from your device.\nDefine your data\nThe first step is to create the application model. You can create a file named model.app with the following content, you just need to change the type value with a unique identifier for your application and the name and revision with the apprioriate value for your use case.\nFirst of all, to be able to send and receive data, you have to describe your data to AirVantage.\nHere is the description, you just need to change the\ntype\nvalue with a unique identifier\nfor your application and the\nname\nand\nrevision\nwith the appropriate values for your use case.\nYou can modify the\n<data>\narea. Once it matches your needs, save everything as\nmodel.app\n.\nDon\u2019t modify the asset id as it is used in the code source application or modify it accordingly\n<?xml version="1.0" encoding="ISO-8859-1"?>\n<app:application\nxmlns:app="',(0,i.jsx)(t.a,{href:"http://www.sierrawireless.com/airvantage/application/1.0",children:"http://www.sierrawireless.com/airvantage/application/1.0"}),'"\ntype="com.test.airvantage.app"\nname="AirVantage Greenhouse"\nrevision="0.0.1">\n<capabilities>']}),"\n",(0,i.jsx)(t.p,{children:'<communication>\n<protocol comm-id="SERIAL" type="REST" />\n</communication>'}),"\n",(0,i.jsxs)(t.p,{children:['<data>\n<encoding type="REST">\n<asset default-label="Greenhouse" id="machine">\n<variable default-label="Temperature" path="temperature"\ntype="double"/>\n<variable default-label="Luminosity" path="luminosity"\ntype="double"/>\n<setting default-label="Threshold" path="threshold"\ntype="int"/>\n</asset>\n</encoding>\n</data>\n</capabilities>\n</app:application>\nZip this file, mine is named\nmodel.app.zip\nGo on Develop Activity > My Apps\nClick on the Release button\nRelease your application\nSelect your file model.app.zip\nOpen Advanced settings and select\nI want to publish my application after releasing it\nFinally, click on Start\nEdit your system\nGo to Inventory > Systems\nSelect your system and click on the Edit icon\nSearch your application\nClick on Search application\nIn the new dialog box, select the My Application tab\nSearch your application using its name (AirVantage Greenhouse)\nAssociate your application to your system\nClick on the application to select it.\nClick on the padlock and configure the password.\nClick on Save in the right top corner\nClick on the Monitor icon to monitor your system\nStep 3: Implementing an application\nOnce your device is registered in AirVantage, you can start developing the embedded application that will use the REST protocol to communicate with\nAirVantage. Here are the different calls to integrate in the embedded application to send and receive data with AirVantage:\nSend and Receive data\nOnce your device is registered in AirVantage, you can start developing the embedded application that will use REST API for devices to communicate with AirVantage. Here are the different calls to integrate in the embedded application to send and receive data with AirVantage:\nInstall tools\nYou can install\nPostman\nfor Chrome or REST Client for Firefox.\nThese tools allow you to use REST API with your browser to test the communication.\nAuthentication\nThe REST API for devices uses HTTP Basic Authentication to authenticate devices. So you need to specify the Authentication header for each API call. The username is the serial number of the gateway in AirVantage and the password is the one set during the creation of the system. Then you need to combine the two into a string \u201Cusername:password\u201D and encode the resulted string using Base64. Finally, you specify the Authentication header in the API calls.\nAuthorization: Basic dG90bzp0b3Rv\nSend data to AirVantage\nYou can use the Messages API to send data from the device to AirVantage. A message can contain several data and several datapoints per data. Then you can easily send a complete status or historical values in one message.\nRequest:\nPOST ',(0,i.jsx)(t.a,{href:"https://na.airvantage.net/device/messages",children:"https://na.airvantage.net/device/messages"}),'\nAuthorization: Basic dG90bzp0b3Rv\nContent-Type: application/json\n[\n{\n"machine.temperature": [{\n"timestamp" : 1349907137000,\n"value" : "23.2"\n},\n{\n"timestamp" : 1349908137000,\n"value" : "24.5"\n},\n{\n"timestamp" : 1349909137000,\n"value" : "22.9"\n}]\n},\n{\n"machine.threshold": [{\n"timestamp" : 1349907137000,\n"value" : "30"\n}]\n}\n]\nThis message sends 3 values for the temperature with different timestamp and one value for the threshold parameter.\nOnce AirVantage receives this message, data are stored and can be accessed by the Data API on System (Last datapoints, Historical aggregated datapoints, Historical raw datapoints, Export datapoints)\nReceive tasks from AirVantage\nA device can not only push data to AirVantage but you can also use AirVantage to request the device to execute some tasks. Currently the REST API for devices supports 2 kind of tasks: read and write.\nA\nread\ntask requests the device to send back to the server the current values for a set of data. It\u2019s a way for a user to request the device to \u201Crefresh\u201D the value of a data on the server. This operation is only for variables and settings. To create this operation from AirVantage API, you need to call the \u201CRetrieve data\u201D API (see documentation of System API).\nA\nwrite\ntask requests the device to change the value of a data locally on the device. It\u2019s a way to interact with the device and change the behaviour of the embedded application. This operation is only available for settings. To create this operation from AirVantage API, you need to call the \u201CApply settings\u201D API (see documentation of System API).\nThe device needs to call periodically the following API:\nRequest:\nGET ',(0,i.jsx)(t.a,{href:"https://na.airvantage.net/device/tasks",children:"https://na.airvantage.net/device/tasks"}),'\nAuthorization: Basic dG90bzp0b3Rv\nResponse:\nHTTP/1.1 200 OK\nContent-Type: application/json\n[\n{\n"uid" : "3c12547b613740adb686271bdc8f097c",\n"timestamp" : 1348836320188,\n"read" : ["machine.temperature"]\n},\n{\n"uid": "8006cc58ba2141f69161a78f1bfdea1d",\n"timestamp": 1348836320566,\n"write" : [{"machine.threshold" : 25}}]\n}\n]\nIn this example, AirVantage is asking to the device to send the current temperature and requests to change the value of the threshold to 25. Once the API is called, AirVantage assumed the tasks have been retrieved by the device and then acknowledge automatically the tasks. In the current example, the device will probably directly call the message API to send back to AirVantage the last value of the temperature.\nNext Step\nContinue the tutorial\nby using tools supplied by AirVantage to test your communication with your device.']})]})}function h(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>s,x:()=>r});var a=n(6540);let i={},o=a.createContext(i);function s(e){let t=a.useContext(o);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),a.createElement(o.Provider,{value:t},e.children)}}}]);